-- Critical notification queues retain source-domain and recipient/admin scope.
create index m15_03_support_notification_health on public.product_regulatory_outbox_events(organization_id,delivery_state,occurred_at,id) where event_type='support_period.alert';
create index m15_03_deadline_notification_health on public.reporting_deadline_alert_deliveries(organization_id,delivery_state,created_at,id);
create index m15_03_chat_notification_health on public.notification_chat_deliveries(organization_id,status,created_at,id);
create or replace function public.m15_03_source_queue(p_org uuid,p_actor uuid,p_source text,p_product uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public set statement_timeout='200ms' as $$
declare n bigint:=0;running bigint:=0;retrying bigint:=0;review bigint:=0;uncertain bigint:=0;failed bigint:=0;oldest timestamptz;extra_uncertain bigint:=0;begin
 case p_source
 when 'connectors' then
 -- Connector runs are organization-scoped. No product narrowing is implied by
 -- an integration mapping; a product-specific request withholds this source.
 if p_product is not null then return null;end if;
 select count(*)filter(where category='pending'),count(*)filter(where category='running'),count(*)filter(where category='retrying'),count(*)filter(where category='review'),count(*)filter(where category='failed'),min(created_at)filter(where category='pending') into n,running,retrying,review,failed,oldest
 from (select v.category,r.created_at from (values('pending','queued'),('running','running'),('retrying','retrying'),('review','waiting_for_review'),('failed','failed'))v(category,state) cross join lateral(select j.created_at from public.sync_runs j join public.connectors c on c.organization_id=p_org and c.id=j.connector_id where j.organization_id=p_org and j.status=v.state order by j.created_at,j.id limit 10000)r)bounded;
 when 'sboms' then
 select count(*)filter(where category='pending'),count(*)filter(where category='running'),count(*)filter(where category='retrying'),count(*)filter(where category='failed'),min(created_at)filter(where category='pending') into n,running,retrying,failed,oldest
 from (select v.category,r.created_at from (values('pending','queued'),('running','processing'),('retrying','failed'),('failed','dead_letter'))v(category,state) cross join lateral(select j.created_at from public.sbom_ingest_jobs j join public.sbom_sources s on s.organization_id=p_org and s.id=j.source_id join public.products p on p.organization_id=p_org and p.id=s.product_id where j.organization_id=p_org and j.status=v.state and (p_product is null or p.id=p_product) order by j.created_at,j.id limit 10000)r)bounded;
 when 'reports' then
 if exists(select 1 from public.report_run_recipients q join public.report_runs r on r.organization_id=p_org and r.id=q.run_id where q.organization_id=p_org and (r.owner_user_id=p_actor or q.user_id=p_actor) and (q.generation_state in ('waiting','running','failed') or q.email_state='uncertain') and not public.m14_04_source_access(p_org,p_actor,r.config) limit 1) then return null;end if;
 select count(*)filter(where category='pending'),count(*)filter(where category='running'),count(*)filter(where category='failed'),count(*)filter(where category='uncertain'),min(created_at)filter(where category='pending') into n,running,failed,uncertain,oldest
 from(select v.category,q.created_at from (values('pending','waiting'),('running','running'),('failed','failed'),('uncertain','ready'))v(category,state) cross join lateral(select q.created_at from public.report_run_recipients q join public.report_runs r on r.organization_id=p_org and r.id=q.run_id where q.organization_id=p_org and q.generation_state=v.state and (v.category<>'uncertain' or q.email_state='uncertain') and (r.owner_user_id=p_actor or q.user_id=p_actor) and public.m14_04_source_access(p_org,p_actor,r.config) and (p_product is null or coalesce(r.config#>>'{report,productId}',r.config#>>'{report,context,productId}')=p_product::text) order by q.created_at,q.id limit 10000)q)bounded;
 when 'notifications' then
 if exists(select 1 from public.notification_dispatches d where d.organization_id=p_org and d.effective_recipient_user_id=p_actor and d.status in ('queued','digest_pending','burst_pending','leased','retrying','failed','exhausted') and not public.m15_03_notification_visible(p_org,p_actor,d,p_product) limit 1) then return null;end if;
 select count(*)filter(where category='pending'),count(*)filter(where category='running'),count(*)filter(where category='retrying'),count(*)filter(where category='review'),count(*)filter(where category='uncertain'),count(*)filter(where category='failed'),min(created_at)filter(where category='pending') into n,running,retrying,review,uncertain,failed,oldest
 from(select v.category,d.created_at from(values('pending','queued'),('pending','digest_pending'),('pending','burst_pending'),('running','leased'),('retrying','retrying'),('failed','failed'),('failed','exhausted'))v(category,state) cross join lateral(select d.created_at from public.notification_dispatches d where d.organization_id=p_org and d.effective_recipient_user_id=p_actor and d.status=v.state and public.m15_03_notification_visible(p_org,p_actor,d,p_product) order by d.created_at,d.id limit 10000)d
 union all
 select v.category,e.occurred_at from(values('pending','pending'),('pending','queued'),('pending','scheduled'),('running','leased'),('retrying','retrying'),('review','recipient_unavailable'),('failed','dead_letter'))v(category,state) cross join lateral(select e.occurred_at from public.product_regulatory_outbox_events e join public.products p on p.organization_id=p_org and p.id=e.product_id and p.archived_at is null join public.product_releases r on r.organization_id=p_org and r.id=e.release_id and r.archived_at is null where e.organization_id=p_org and e.event_type='support_period.alert' and e.delivery_state=v.state and e.obsolete_at is null and coalesce(e.original_recipient_user_id,p.responsible_owner_id,e.delivered_to_user_id)=p_actor and public.m14_03_actor_can(p_org,p_actor,'can_view_products') and (p_product is null or e.product_id=p_product) order by e.occurred_at,e.id limit 10000)e
 union all
 select v.category,d.created_at from(values('pending','queued'),('running','leased'),('retrying','retrying'),('failed','dead_letter'))v(category,state) cross join lateral(select d.created_at from public.reporting_deadline_alert_deliveries d cross join lateral(select public.m12_05_chat_source_current(p_org,p_actor,'m6_deadline',d.alert_id,array[]::uuid[])j) authority where d.organization_id=p_org and d.delivery_state=v.state and p_actor in(d.original_recipient_user_id,d.prepared_recipient_user_id,d.recipient_user_id) and public.m14_03_actor_can(p_org,p_actor,'can_view_reporting') and authority.j->>'active'='true' and (p_product is null or authority.j->>'productId'=p_product::text) order by d.created_at,d.id limit 10000)d
 union all
 select v.category,d.created_at from(values('pending','queued'),('running','attempted'),('retrying','failed'),('uncertain','uncertain'),('failed','exhausted'))v(category,state) cross join lateral(select d.created_at from public.notification_chat_deliveries d cross join lateral(select public.m12_05_chat_source_current(p_org,p_actor,d.source_kind,d.source_id,case when d.source_product_id is null then array[]::uuid[] else array[d.source_product_id] end)j) authority where d.organization_id=p_org and d.status=v.state and public.m12_05_chat_auditor(p_org,p_actor) and authority.j->>'active'='true' and case when d.source_kind in ('m2_support') then public.m14_03_actor_can(p_org,p_actor,'can_view_products') when d.source_kind in ('m5_triage','m5_approval') then public.m14_03_actor_can(p_org,p_actor,'can_view_findings') and public.m14_03_actor_can(p_org,p_actor,'can_view_products') when d.source_kind in ('m6_deadline','m6_approval') then public.m14_03_actor_can(p_org,p_actor,'can_view_reporting') when d.source_kind='m8_evidence' then public.m14_03_actor_can(p_org,p_actor,'can_view_evidence') and public.m14_03_actor_can(p_org,p_actor,'can_view_products') when d.source_kind='m9_owner' then public.m14_03_actor_can(p_org,p_actor,'can_view_suppliers') and public.m14_03_actor_can(p_org,p_actor,'can_view_products') else false end and (p_product is null or d.source_product_id=p_product) order by d.created_at,d.id limit 10000)d
)bounded;
 -- Scheduled email uncertainty is tenant/recipient scoped and requires the
 -- current report source authority. It is distinct from an ordinary retry.
 select count(*) into extra_uncertain from(select q.id from public.report_run_recipients q join public.report_runs r on r.organization_id=p_org and r.id=q.run_id where q.organization_id=p_org and q.user_id=p_actor and q.email_state='uncertain' and public.m14_04_source_access(p_org,p_actor,r.config) and (p_product is null or coalesce(r.config#>>'{report,productId}',r.config#>>'{report,context,productId}')=p_product::text) order by q.created_at,q.id limit 10000)q;
 uncertain:=uncertain+extra_uncertain;
 when 'exports' then
 if exists(select 1 from public.export_jobs j where j.organization_id=p_org and j.requester_id=p_actor and j.state in ('queued','capturing','audit_pending','rendering','failed') and not public.m14_04_source_actor_access(p_org,p_actor,j.source,j.context) limit 1)
 or (not public.m14_03_actor_can(p_org,p_actor,'can_export_organization') and exists(select 1 from public.organization_export_jobs where organization_id=p_org and actor_user_id=p_actor and status in ('queued','running','failed','paused','dead_letter') limit 1))
 or (not(public.m14_03_actor_can(p_org,p_actor,'can_view_evidence') and public.m14_03_actor_can(p_org,p_actor,'can_export_evidence') and public.m14_03_actor_can(p_org,p_actor,'can_view_products')) and exists(select 1 from public.evidence_document_watermark_exports where organization_id=p_org and requested_by_user_id=p_actor and status in ('queued','claimed','failed') limit 1)) then return null;end if;
 select count(*)filter(where category='pending'),count(*)filter(where category='running'),count(*)filter(where category='retrying'),count(*)filter(where category='review'),count(*)filter(where category='failed'),min(created_at)filter(where category='pending') into n,running,retrying,review,failed,oldest from (
 select v.category,j.requested_at created_at from(values('pending','queued'),('running','capturing'),('running','audit_pending'),('running','rendering'),('failed','failed'))v(category,state) cross join lateral(select j.requested_at from public.export_jobs j where j.organization_id=p_org and j.requester_id=p_actor and j.state=v.state and public.m14_04_source_actor_access(p_org,p_actor,j.source,j.context) and (p_product is null or j.context->>'productId'=p_product::text) order by j.requested_at,j.id limit 10000)j
 union all
 select v.category,j.created_at from(values('pending','queued'),('running','running'),('retrying','failed'),('review','paused'),('failed','dead_letter'))v(category,state) cross join lateral(select j.created_at from public.organization_export_jobs j where p_product is null and j.organization_id=p_org and j.actor_user_id=p_actor and j.status=v.state and public.m14_03_actor_can(p_org,p_actor,'can_export_organization') order by j.created_at,j.id limit 10000)j
 union all
 select v.category,j.created_at from(values('pending','queued'),('running','claimed'),('failed','failed'))v(category,state) cross join lateral(select j.created_at from public.evidence_document_watermark_exports j join public.products p on p.organization_id=p_org and p.id=j.product_id where j.organization_id=p_org and j.requested_by_user_id=p_actor and j.status=v.state and public.m14_03_actor_can(p_org,p_actor,'can_view_evidence') and public.m14_03_actor_can(p_org,p_actor,'can_export_evidence') and public.m14_03_actor_can(p_org,p_actor,'can_view_products') and (p_product is null or j.product_id=p_product) order by j.created_at,j.id limit 10000)j
 )bounded;
 else return null;end case;
 return public.m15_03_queue(p_source,n,running,retrying,review,uncertain,failed,oldest,statement_timestamp());end $$;
notify pgrst,'reload schema';
